from __future__ import annotations

import html
import json
from datetime import datetime, timezone
from pathlib import Path


def render_dashboard(payload: dict) -> str:
    scenes = payload["scenes"]
    total = sum(scene["duration_sec"] for scene in scenes)
    rows = []
    for scene in scenes:
        rows.append(
            "<tr>"
            f"<td>{scene['id']}</td>"
            f"<td>{scene['start_sec']:.3f}</td>"
            f"<td>{scene['duration_sec']:.3f}</td>"
            f"<td>{html.escape(scene['text'])}</td>"
            f"<td>{html.escape(scene['source'])}</td>"
            "</tr>"
        )
    page = f"""<!doctype html>
<html lang="ru"><meta charset="utf-8"><title>Video Assembler Dashboard</title>
<style>body{{font:15px system-ui;margin:32px;background:#111;color:#eee}}table{{border-collapse:collapse;width:100%}}th,td{{padding:9px;border-bottom:1px solid #333;text-align:left;vertical-align:top}}th{{color:#9ad}}.meta{{margin:12px 0 24px;color:#aaa}}</style>
<h1>Тестовый дашборд раскадровки</h1>
<div class="meta">Канал: {html.escape(payload['channel'])} · Сцен: {len(scenes)} · Длительность: {total:.3f} с</div>
<table><thead><tr><th>ID</th><th>Начало</th><th>Длительность</th><th>Текст</th><th>Источник</th></tr></thead>
<tbody>{''.join(rows)}</tbody></table></html>"""
    return page


def render_review(payload: dict) -> str:
    data = json.dumps(payload, ensure_ascii=False).replace("</", "<\\/")
    page = f"""<!doctype html>
<html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Предпросмотр — Video Assembler</title>
<style>
:root{{color-scheme:dark}}*{{box-sizing:border-box}}body{{margin:0;background:#0e0f12;color:#e7e7ea;font:14px/1.5 system-ui,sans-serif}}
header{{position:sticky;top:0;z-index:10;background:#15161aeF;border-bottom:1px solid #2a2c33;padding:11px 20px;display:flex;gap:12px;align-items:center;flex-wrap:wrap;backdrop-filter:blur(8px)}}
h1{{font-size:15px;margin:0}}.sub{{color:#9a9aa2;font-size:13px}}.spacer{{flex:1}}button,.upload{{background:#2b2d36;color:#e7e7ea;border:1px solid #3a3d48;border-radius:7px;padding:7px 11px;font:inherit;cursor:pointer}}button:hover,.upload:hover{{background:#343742}}
#count{{font-weight:700}}#need{{background:#f59e0b;color:#1a1400;border-color:#f59e0b;font-weight:700}}#grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:16px;padding:20px;max-width:1640px;margin:auto}}
.card{{background:#17181d;border:1px solid #262830;border-radius:12px;overflow:hidden}}.card.marked{{border-color:#e04a3a;box-shadow:0 0 0 2px #e04a3a55}}.thumb{{position:relative;aspect-ratio:16/9;background:#0b0b0d;display:flex;align-items:center;justify-content:center;color:#6b6b73}}.thumb img{{width:100%;height:100%;object-fit:cover;display:block}}.num{{position:absolute;left:8px;top:8px;background:#000b;padding:2px 8px;border-radius:6px;font-weight:700}}.badge{{position:absolute;right:8px;top:8px;background:#16a34a;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700}}figcaption{{padding:10px 13px 13px}}.meta{{color:#8b8b93;font-size:12px}}.query{{color:#7f8ea3;font-size:12px;margin:4px 0;word-break:break-word}}.txt{{margin:0;color:#d7d7db}}.acts{{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}}.acts button{{font-size:12px;padding:6px 9px}}.acts .on{{background:#e04a3a;border-color:#e04a3a}}.acts .keep{{background:#1f5133;border-color:#2f7a4c}}.acts .ban{{background:#5c1f22;border-color:#8c2f34}}.upload{{display:inline-block}}input[type=file]{{display:none}}textarea{{display:none;width:100%;min-height:54px;margin-top:9px;background:#0e0f12;color:#e7e7ea;border:1px solid #3a3d48;border-radius:7px;padding:7px;font:inherit;resize:vertical}}.marked textarea{{display:block}}.need{{display:none;background:#f59e0b;color:#1a1400;font-weight:800;text-align:center;padding:5px;font-size:12px}}.card.needup .need{{display:block}}
.opts{{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}}.opt{{position:relative;width:92px;height:62px;padding:0;overflow:hidden;border-radius:6px;background:#0b0b0d;border:2px solid transparent}}.opt:hover{{border-color:#46d39a}}.opt img{{width:100%;height:100%;object-fit:cover;display:block}}.opt span{{position:absolute;left:2px;right:2px;bottom:2px;background:#000b;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}}
.overlay{{margin-top:10px;padding:9px;border:1px solid #6a4d8c;border-radius:8px;background:#1e1830}}.overlay.closed{{display:none}}.overlay input,.overlay select{{background:#0e0f12;color:#e7e7ea;border:1px solid #3a3d48;border-radius:5px;padding:5px;width:82px;margin:2px}}.overlay input[type=text]{{width:100%}}.overlay button{{font-size:11px;padding:5px 8px;margin:3px 2px 0 0}}.overlay .ok{{background:#1f6b4f;border-color:#2f8f6a}}.overlay .clear{{background:#5c1f22;border-color:#8c2f34}}
.overlay .photo{{display:inline-block;background:#243b5e;border:1px solid #3a5a8c;padding:5px 8px;border-radius:5px;font-size:11px}}.overlay-variants{{margin:-2px 0 8px;padding:6px;border:1px solid #385b86;border-radius:6px;background:#142238;font-size:11px}}.overlay-variants img{{display:block;width:100%;max-height:150px;object-fit:cover;margin-top:5px;border-radius:4px}}.live-overlay{{position:absolute;z-index:4;max-width:42%;max-height:42%;padding:4px 7px;background:rgba(36,24,64,.92);border:2px solid #d6a7ff;border-radius:5px;color:#fff;font-size:10px;text-align:center;box-shadow:0 2px 8px #000;pointer-events:none}}.live-overlay img{{display:block;max-width:100px;max-height:60px;object-fit:contain}}.live-overlay.tl{{left:7px;top:7px}}.live-overlay.tr{{right:7px;top:7px}}.live-overlay.c{{left:50%;top:50%;transform:translate(-50%,-50%)}}.live-overlay.bl{{left:7px;bottom:7px}}.live-overlay.br{{right:7px;bottom:7px}}
.position-controls{{display:flex;align-items:center;gap:3px;margin:4px 0;color:#cfc4e5;font-size:10px}}.position-controls button{{min-width:25px;padding:3px 5px!important}}.position-controls button.on{{background:#4d2870;border-color:#d6a7ff}}
.thumb video{{width:100%;height:100%;object-fit:cover;display:block}}
.ovpic{{display:block;width:100%;max-height:150px;object-fit:cover;margin:5px 0;border-radius:4px;border:1px solid #385b86}}
#offline{{display:none;background:#f59e0b;color:#1a1400;font-weight:700;padding:7px 20px;text-align:center}}
</style><body><header><h1>Предпросмотр видеоряда</h1><span class="sub" id="summary"></span><span class="spacer"></span><span class="sub">отмечено: <b id="count">0</b></span><button id="need">⚠️ нужно твоё фото: 0</button><button id="export">📋 Показать правки</button><button id="download">💾 Скачать правки</button><button id="approve">✅ Утвердить ролик</button><button id="reset">Сбросить</button></header><div id="offline">АВТОНОМНЫЙ РЕЖИМ: сервер не отвечает. Кадры и всплывашки видны, отметки и заметки работают; замена кадра, поиск и утверждение недоступны.</div><main id="grid"></main>
<script>
const payload={data}; const state=JSON.parse(localStorage.getItem('video-assembler-review')||'{{}}'); state._overlays=payload.overlays||{{}};
// Кадры и всплывашки вшиты в страницу ОТНОСИТЕЛЬНЫМИ путями, поэтому артефакт,
// открытый файлом с диска, показывает всё сразу. Сервер — только улучшение.
for(const [id,a] of Object.entries(payload.assets||{{}})){{state[id]=state[id]||{{}};if(a.image&&!state[id].uploaded)state[id].image=a.image;if(a.video&&!state[id].uploaded)state[id].video=a.video;if(a.status==='failed')state[id].need=true}}
const grid=document.querySelector('#grid'); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));
function overlayVariants(p){{return (p.variants||[]).map((v,i)=>v.kind==='photo'?`<button class="overlay-opt" data-a="overlay-pick" data-index="${{i}}"><img src="${{esc(v.thumb||v.full||v.path||'')}}"><span>Фото-вариант ${{i+1}}</span></button>`:`<button class="overlay-opt text-opt" data-a="overlay-text-pick" data-index="${{i}}">Текст: ${{esc(v.words||'вариант')}}</button>`).join('')}}
function card(s){{const x=state[s.id]||{{}};const planned=(state._overlays||{{}})[String(s.id)]||{{}};const ov=planned.text||{{}};const inline=planned.photo?`<div class="live-overlay tr"><img src="/${{esc(planned.photo)}}"></div>`:(ov.words?`<div class="live-overlay tr"><b>${{esc(ov.words)}}</b></div>`:'');const opts=(x.options||[]).map((o,i)=>{{const media=o.thumb||((o.kind==='photo'||o.kind==='video')?o.full:'');return `<button class="opt" data-a="pick" data-index="${{i}}">${{media?`<img src="${{esc(media)}}" onerror="this.style.display='none';this.nextElementSibling.style.display='block'">`:`<span class="webopt">${{esc(o.title||o.full||'веб-страница')}}</span>`}}<span>${{esc(o.src||o.kind||'')}}</span></button>`}}).join('');return `<figure class="card ${{x.mark?'marked ':''}}${{x.need?'needup':''}}" data-id="${{s.id}}"><div class="thumb">${{x.image?`<img src="${{x.image}}">`:'кадр ещё не найден'}}${{inline}}<span class="num">${{s.id}}</span><span class="badge">${{esc(s.source)}}</span></div><div class="need">⚠️ НУЖНО ТВОЁ ФОТО</div><figcaption><div class="meta">СЦЕНА ${{String(s.id).padStart(2,'0')}} · ${{s.start_sec.toFixed(1)}} с · ${{s.duration_sec.toFixed(1)}} с</div><div class="query">${{esc(s.source_query)}}</div><p class="txt">${{esc(s.text)}}</p><div class="acts"><button data-a="edit">✏️ Изменить кадр</button><button data-a="search">🔍 Искать</button><label class="upload">⬆️ Загрузить<input type="file" accept="image/*" data-a="upload"></label><button class="keep" data-a="keep">✓ Оставить</button><button class="ban" data-a="ban">✕ Забраковать</button></div><div class="opts">${{opts}}</div><div class="overlay"><b>ВСПЛЫВАШКА ${{planned.planned?'· ЗАПЛАНИРОВАНА':''}}</b><div class="overlay-variants">${{overlayVariants(planned)}}</div>${{planned.photo?`<img class="ovpic" src="${{esc(planned.photo)}}">`:''}}<input type="text" data-f="words" value="${{esc(ov.words||'')}}" placeholder="Текст всплывашки"><input type="number" step="0.01" data-f="at" value="${{planned.at??0.35}}"><input type="number" step="0.1" data-f="scale" value="${{planned.scale??1}}"><select data-f="shape"><option ${{planned.shape==='rect'?'selected':''}}>rect</option><option ${{planned.shape==='rounded'?'selected':''}}>rounded</option><option ${{planned.shape==='square'?'selected':''}}>square</option><option ${{planned.shape==='circle'?'selected':''}}>circle</option></select><select data-f="sound"><option ${{planned.sound==='pop'?'selected':''}}>pop</option><option>whoosh</option><option>ding</option><option>pshik</option></select><button data-a="overlay-save">Сохранить</button><button class="ok" data-a="overlay-approve">✓ Подтвердить</button><button class="clear" data-a="overlay-clear">✕ Очистить</button></div><textarea placeholder="Что изменить или почему забраковано?">${{esc(x.note||'')}}</textarea></figcaption></figure>`}}
function installOverlayUploads(){{}}
function installSearchControls(){{document.querySelectorAll('.card').forEach(c=>{{const id=c.dataset.id,acts=c.querySelector('.acts'),p=c.querySelector('.overlay');if(!acts)return;acts.querySelectorAll('.upload').forEach(x=>x.remove());if(!acts.querySelector('[data-f=search-q]')){{const input=document.createElement('input');input.className='search-q';input.dataset.f='search-q';input.placeholder='Что искать';input.value=state[id]?.search_q||'';const mic=document.createElement('button');mic.type='button';mic.dataset.a='voice';mic.textContent='🎙️';mic.title='Надиктовать запрос';acts.prepend(mic,input)}}if(p&&!p.querySelector('[data-f=overlay-q]')){{const input=document.createElement('input');input.className='overlay-search-q';input.dataset.f='overlay-q';input.placeholder='Что искать для всплывашки';input.value=state[id]?.overlay_q||'';const mic=document.createElement('button');mic.type='button';mic.dataset.a='overlay-voice';mic.textContent='🎙️';mic.title='Надиктовать запрос для всплывашки';const search=document.createElement('button');search.type='button';search.dataset.a='overlay-search';search.textContent='🔍 Искать';p.insertBefore(input,p.firstChild);p.insertBefore(mic,p.firstChild);p.insertBefore(search,p.firstChild)}}}})}}
function installVideoPreviews(){{document.querySelectorAll('.card').forEach(c=>{{const x=state[c.dataset.id];if(!x?.video)return;const thumb=c.querySelector('.thumb');thumb.innerHTML=`<video controls muted preload="metadata" src="${{esc(x.video)}}"></video><span class="num">${{c.dataset.id}}</span>`}})}}
function installOptionCollapse(){{document.querySelectorAll('.card').forEach(c=>{{const id=c.dataset.id,x=state[id]||{{}},opts=c.querySelector('.opts');if(!opts||!opts.children.length)return;let toggle=c.querySelector('.options-toggle');if(!toggle){{toggle=document.createElement('button');toggle.type='button';toggle.className='options-toggle';toggle.textContent='Показать варианты поиска';opts.parentNode.insertBefore(toggle,opts)}}const apply=()=>{{const closed=state[id]?.optionsCollapsed===true;opts.style.display=closed?'none':'flex';toggle.textContent=closed?'Показать варианты поиска':'Свернуть варианты поиска'}};toggle.onclick=()=>{{state[id]=state[id]||{{}};state[id].optionsCollapsed=!state[id].optionsCollapsed;save()}};apply()}})}}
function installOverlayOnFrames(){{}}
function render(){{grid.innerHTML=payload.scenes.map(card).join('');installOverlayUploads();installSearchControls();installVideoPreviews();installOverlayOnFrames();installOptionCollapse();document.querySelector('#summary').textContent=`${{payload.scenes.length}} сцен · ${{payload.scenes.reduce((a,s)=>a+s.duration_sec,0).toFixed(1)}} с`;const vals=Object.values(state);document.querySelector('#count').textContent=vals.filter(x=>x.mark||x.need).length;document.querySelector('#need').textContent=`⚠️ нужно твоё фото: ${{vals.filter(x=>x.need).length}}`}}
function save(){{localStorage.setItem('video-assembler-review',JSON.stringify(state));render()}}
async function api(path,options={{}}){{const r=await fetch(path,options);if(!r.ok)throw new Error(await r.text());return r.json()}}
async function refreshState(){{if(window._voiceActive)return;try{{const live=await api('/state?_probe=1');state._overlays=live.overlays||state._overlays||{{}};for(const s of live.scenes){{state[s.id]=state[s.id]||{{}};if(s.thumb)state[s.id].image=s.thumb;if(s.video)state[s.id].video=s.video;if(s.status==='failed')state[s.id].need=true}}document.querySelector('#offline').style.display='none';render()}}catch(e){{
// Сервера нет: страница уже всё показала из вшитых данных. Говорим об этом
// человеку и ПРЕКРАЩАЕМ опрос, вместо молчаливого стука в никуда.
document.querySelector('#offline').style.display='block';if(window._poll){{clearInterval(window._poll);window._poll=null}}}}}}
grid.addEventListener('click',async e=>{{const b=e.target.closest('[data-a^="overlay-"]');if(!b||['overlay-text-save','overlay-voice','overlay-search','overlay-pick','overlay-text-pick'].includes(b.dataset.a))return;const c=b.closest('.card'),id=c.dataset.id,p=c.querySelector('.overlay');try{{if(b.dataset.a==='overlay-clear'){{state._overlays[id]={{cleared:true}};save();await api('/overlay?id='+id+'&clear=1',{{method:'POST'}})}}else{{const body={{sound:p.querySelector('[data-f=sound]').value,at:Number(p.querySelector('[data-f=at]').value),shape:p.querySelector('[data-f=shape]').value,scale:Number(p.querySelector('[data-f=scale]').value),approved:b.dataset.a==='overlay-approve',text:{{words:p.querySelector('[data-f=words]').value,at:Number(p.querySelector('[data-f=at]').value),scale:Number(p.querySelector('[data-f=scale]').value),sound:p.querySelector('[data-f=sound]').value}}}};
// Правка всплывашки сначала ложится В СТРАНИЦУ, и только потом уходит на
// сервер, если он есть. Без этого решение терялось при каждом «нет сервера».
state._overlays[id]=Object.assign({{}},state._overlays[id]||{{}},body);save();
await api('/overlay?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(body)}})}}await refreshState()}}catch(err){{}}}});
grid.addEventListener('click',async e=>{{const b=e.target.closest('[data-a="overlay-text-save"]');if(!b)return;const c=b.closest('.card'),id=c.dataset.id,p=c.querySelector('.overlay');const pos=p.querySelector('[data-f=textpos]').value;if(pos.startsWith('b')){{alert('Нижняя строка запрещена: там будут субтитры');return}}const words=p.querySelector('[data-f=words]').value;const scene=(payload.scenes.find(s=>String(s.id)===String(id))||{{}}).text||'';
// Надпись не может быть дословной копией озвучки: она обязана ДОБАВЛЯТЬ то,
// чего в кадре и в тексте нет. Проверка одной строкой, здесь же.
if(words.trim()&&scene.toLowerCase().replace(/\\s+/g,' ').includes(words.trim().toLowerCase().replace(/\\s+/g,' '))){{alert('Это дословная копия озвучки. Надпись должна ДОБАВЛЯТЬ: число, дату, имя, факт — 3-5 слов капсом.');return}}
const body={{words,color:p.querySelector('[data-f=color]').value,font:p.querySelector('[data-f=font]').value,pos,at:Number(p.querySelector('[data-f=at]').value),scale:Number(p.querySelector('[data-f=scale]').value),sound:p.querySelector('[data-f=sound]').value}};
state._overlays[id]=Object.assign({{}},state._overlays[id]||{{}},{{text:body}});save();
try{{await api('/overlay_text?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(body)}});await refreshState()}}catch(err){{}}}});
grid.addEventListener('click',async e=>{{const b=e.target.closest('[data-a="ticker-save"]');if(!b)return;const c=b.closest('.card'),id=c.dataset.id,p=c.querySelector('.overlay');try{{await api('/ticker?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{words:p.querySelector('[data-f=ticker]').value,at:Number(p.querySelector('[data-f=at]').value),sound:p.querySelector('[data-f=sound]').value}})}});await refreshState()}}catch(err){{alert('Ошибка ticker API: '+err.message)}}}});
grid.addEventListener('click',async e=>{{const b=e.target.closest('[data-a="overlay-pick"],[data-a="overlay-text-pick"]');if(!b)return;const c=b.closest('.card'),id=c.dataset.id,x=state[id]||{{}},planned=state._overlays?.[String(id)]||{{}},v=(planned.variants||[])[Number(b.dataset.index)];try{{if(b.dataset.a==='overlay-text-pick'){{const input=c.querySelector('[data-f=words]');input.value=v.words||'';input.dispatchEvent(new Event('input',{{bubbles:true}}));return}}const result=await api('/pick_opt?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{...v,target:'overlay'}})}});state._overlays[String(id)]=Object.assign({{}},planned,{{photo:result.path}});save();await refreshState()}}catch(err){{alert('Не удалось выбрать всплывашку: '+err.message)}}}});
grid.addEventListener('click',async e=>{{const b=e.target.closest('button');if(!b)return;const c=b.closest('.card'),id=c.dataset.id,x=state[id]||{{}};try{{if(b.dataset.a==='edit'||b.dataset.a==='search'){{const input=c.querySelector('[data-f=search-q]');const q=(input?.value||'').trim();if(!q){{alert('Введите поисковый запрос или надиктуйте его');return}}x.mark=true;x.search_q=q;x.note='Поиск: '+q;const result=await api('/search_opts?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{q:q}})}});x.options=result.options||[];if(!x.options.length&&result.errors?.length)x.note+=' Нет ответа: '+result.errors.map(v=>v.source).join(', ')}}if(b.dataset.a==='pick'){{const option=x.options[Number(b.dataset.index)];const result=await api('/pick_opt?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{...option,target:'scene'}})}});x.image='/'+result.path+'?v='+Date.now();x.optionsCollapsed=true;x.mark=true;x.need=false}}if(b.dataset.a==='keep'){{x.mark=false;x.need=false;x.verdict='keep';await api('/keepimg?id='+id,{{method:'POST'}})}}if(b.dataset.a==='ban'){{x.mark=true;x.need=true;x.verdict='ban';await api('/ban_asset?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{}})}})}}state[id]=x;save()}}catch(err){{
// Сервера нет — решение человека НЕ ТЕРЯЕТСЯ: оно остаётся в странице и уедет
// в review_changes.json по кнопке «Скачать правки». Поиск и замена кадра без
// сервера действительно недоступны, об этом говорит полоса сверху.
if(b.dataset.a==='edit'||b.dataset.a==='search')x.note=(x.note||'')+' (поиск недоступен без сервера)';
state[id]=x;save()}}}});
grid.addEventListener('input',e=>{{const c=e.target.closest('.card');if(!c)return;const id=c.dataset.id;state[id]=state[id]||{{}};if(e.target.tagName==='TEXTAREA')state[id].note=e.target.value;if(e.target.dataset.f==='search-q')state[id].search_q=e.target.value;if(e.target.dataset.f==='overlay-q')state[id].overlay_q=e.target.value;localStorage.setItem('video-assembler-review',JSON.stringify(state))}});
// Загруженное человеком фото ужимается и хранится В САМОЙ СТРАНИЦЕ как data
// URL: одного имени локального файла сборке недостаточно, она его не видит.
async function shrink(file,max){{const url=await new Promise(r=>{{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.readAsDataURL(file)}});const img=await new Promise(r=>{{const i=new Image();i.onload=()=>r(i);i.src=url}});const k=Math.min(1,max/Math.max(img.width,img.height));const cv=document.createElement('canvas');cv.width=Math.round(img.width*k);cv.height=Math.round(img.height*k);cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);return cv.toDataURL('image/jpeg',0.86)}}
grid.addEventListener('change',async e=>{{if(e.target.dataset.a!=='upload')return;const f=e.target.files[0];if(!f)return;const id=e.target.closest('.card').dataset.id;const data=await shrink(f,1920);state[id]=state[id]||{{}};state[id].image=data;state[id].upload=data;state[id].uploaded=true;state[id].mark=true;state[id].need=false;state[id].verdict='replace';save();try{{await fetch('/upload?id='+id,{{method:'POST',headers:{{'X-Filename':encodeURIComponent(f.name),'Content-Type':f.type||'application/octet-stream'}},body:await f.arrayBuffer()}})}}catch(err){{}}}});
grid.addEventListener('change',async e=>{{if(e.target.dataset.a!=='overlay-upload')return;const f=e.target.files[0];if(!f)return;const id=e.target.closest('.card').dataset.id;try{{await fetch('/overlay_photo?id='+id,{{method:'POST',headers:{{'X-Filename':encodeURIComponent(f.name),'Content-Type':f.type||'application/octet-stream'}},body:await f.arrayBuffer()}});await refreshState()}}catch(err){{alert('Ошибка загрузки фото-всплывашки: '+err.message)}}}});
document.querySelector('#reset').onclick=()=>{{localStorage.removeItem('video-assembler-review');Object.keys(state).forEach(k=>delete state[k]);render()}};document.querySelector('#export').onclick=()=>{{const out=payload.scenes.map(s=>{{const x=state[s.id];return x&&(x.mark||x.need)?`Сцена ${{s.id}}: ${{x.note||'нужна правка'}}`:''}}).filter(Boolean).join('\\n');alert(out||'Правок пока нет')}};
// Решения человека уезжают в сборку ОДНИМ ФАЙЛОМ. До этого они умирали у него
// на диске: render.py не читал approval.json вообще, а джоб render рендерил
// артефакт того же прогона, то есть до того, как человек что-то увидел.
function changes(){{const scenes={{}};for(const s of payload.scenes){{const x=state[String(s.id)]||{{}};const o=state._overlays[String(s.id)]||{{}};const item={{}};if(x.verdict)item.verdict=x.verdict;if(x.note)item.note=x.note;if(x.upload)item.upload=x.upload;if(x.need)item.need=true;if(o&&(o.cleared||o.words||o.text||o.at!==undefined||o.scale!==undefined||o.sound||o.shape))item.overlay=o;if(Object.keys(item).length)scenes[String(s.id)]=item}}return {{version:1,channel:payload.channel,approved:!!state._approved,generated_at:new Date().toISOString(),scenes}}}}
function download(name,text){{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{{type:'application/json'}}));a.download=name;document.body.appendChild(a);a.click();a.remove()}}
document.querySelector('#download').onclick=()=>{{const data=changes();download('review_changes.json',JSON.stringify(data,null,2));const n=Object.keys(data.scenes).length;alert('review_changes.json сохранён. Правок в нём: '+n+(data.approved?' · ролик утверждён':' · ролик НЕ утверждён'))}};
document.querySelector('#approve').onclick=async()=>{{if(Object.entries(state).some(([k,x])=>k!=='_overlays'&&k!=='_approved'&&x&&x.need)){{alert('Сначала закройте жёлтые карточки');return}}state._approved=true;save();try{{await api('/approve',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{approved:true}})}});alert('Ролик утверждён для render')}}catch(e){{alert('Ролик утверждён. Сервера нет — нажмите «💾 Скачать правки» и отдайте review_changes.json сборке.')}}}};render();refreshState();
grid.addEventListener('input',e=>{{if(e.target.dataset.f==='search-q'){{const id=e.target.closest('.card').dataset.id;state[id]=state[id]||{{}};state[id].search_q=e.target.value;state[id].note=e.target.value}}}});
grid.addEventListener('click',e=>{{const b=e.target.closest('[data-a=voice],[data-a=overlay-voice]');if(!b)return;e.preventDefault();e.stopPropagation();const c=b.closest('.card');const input=c.querySelector(b.dataset.a==='overlay-voice'?'[data-f=overlay-q]':'[data-f=search-q]');const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){{alert('Голосовой ввод не поддерживается этим браузером. Откройте review.html в Edge/Chrome и разрешите микрофон для localhost.');return}}const old=b.textContent;b.disabled=true;b.textContent='⏺️ Слушаю…';window._voiceActive=true;const r=new R();r.lang='ru-RU';r.interimResults=false;r.continuous=false;r.onstart=()=>{{window._voiceActive=true}};r.onresult=ev=>{{input.value=ev.results[0][0].transcript;input.dispatchEvent(new Event('input',{{bubbles:true}}))}};r.onerror=ev=>{{if(ev.error!=='aborted')alert('Микрофон: '+(ev.error||'браузер не дал доступ'));}};r.onend=()=>{{window._voiceActive=false;b.disabled=false;b.textContent=old;window._poll=window._poll||setInterval(refreshState,2500)}};try{{r.start()}}catch(err){{window._voiceActive=false;b.disabled=false;b.textContent=old;alert('Микрофон: '+err.message)}}}});
grid.addEventListener('click',async e=>{{const b=e.target.closest('[data-a=overlay-search]');if(!b)return;const c=b.closest('.card'),id=c.dataset.id,x=state[id]||{{}},input=c.querySelector('[data-f=overlay-q]'),q=(input?.value||'').trim();if(!q){{alert('Введите запрос для всплывашки или надиктуйте его');return}}try{{const result=await api('/search_opts?id='+id,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{q:q}})}});x.overlay_options=result.options||[];x.overlay_q=q;x.mark=true;state[id]=x;save()}}catch(err){{alert('Поиск всплывашки: '+err.message)}}}});
window._poll=setInterval(refreshState,2500);grid.addEventListener('focusin',e=>{{if(e.target.matches('input,textarea,select')&&window._poll){{clearInterval(window._poll);window._poll=null}}}});grid.addEventListener('focusout',e=>{{if(e.target.matches('input,textarea,select')&&!window._poll)window._poll=setInterval(refreshState,2500)}});
</script></body></html>"""
    return page.replace('src="/', 'src="')


def write_outputs(payload: dict, output_dir: Path) -> None:
    output_dir.mkdir(parents=True, exist_ok=True)
    (output_dir / "scenes.json").write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    (output_dir / "dashboard.html").write_text(render_dashboard(payload), encoding="utf-8")
    review_html = render_review(payload).replace('src="/', 'src="')
    (output_dir / "review.html").write_text(review_html, encoding="utf-8")
    manifest = {
        "status": "dashboard_ready",
        "scene_count": len(payload["scenes"]),
        "duration_sec": round(sum(scene["duration_sec"] for scene in payload["scenes"]), 3),
        "outputs": ["scenes.json", "dashboard.html", "review.html", "manifest.json"],
        "generated_at": datetime.now(timezone.utc).isoformat(),
    }
    (output_dir / "manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def write_static_review(root: Path) -> None:
    """Create an artifact-only review page that works without localhost/API."""
    payload = json.loads((root / "scenes.json").read_text(encoding="utf-8"))
    manifest = json.loads((root / "images" / "manifest.json").read_text(encoding="utf-8")) if (root / "images" / "manifest.json").exists() else {}
    cards = []
    for s in payload.get("scenes", []):
        item = manifest.get(str(s["id"]), {})
        src = item.get("path", "")
        cards.append(f'<article data-id="{s["id"]}"><img src="{html.escape(src)}"><b>СЦЕНА {s["id"]}</b><p>{html.escape(s.get("text", ""))}</p><button data-v="ok">✓ Оставить</button><button data-v="bad">✕ Брак</button></article>')
    page = """<!doctype html><meta charset="utf-8"><title>Review</title><style>body{font:14px system-ui;background:#111;color:#eee;margin:20px}main{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:14px}article{background:#1b1c21;padding:10px;border-radius:10px}img{width:100%;aspect-ratio:16/9;object-fit:cover;background:#000}button{padding:7px;margin:3px;cursor:pointer}.bad{border:2px solid #e44}</style><h1>Review · локальный просмотр без сервера</h1><p id="status"></p><main>""" + "".join(cards) + """</main><script>const state={};document.querySelectorAll('article').forEach(a=>a.onclick=e=>{if(!e.target.dataset.v)return;state[a.dataset.id]=e.target.dataset.v;a.classList.toggle('bad',e.target.dataset.v==='bad');document.querySelector('#status').textContent=Object.keys(state).length+' сцен отмечено';localStorage.review=JSON.stringify(state)});</script>"""
    (root / "review_static.html").write_text(page, encoding="utf-8")
